import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.Cg_noeTw.js";const g=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"scarab","text":"config & template expertise","tagline":"generic config loading and templated content packs — the seal that validates what runs","actions":[{"theme":"brand","text":"Getting Started","link":"/tutorials/getting-started"},{"theme":"alt","text":"Architecture","link":"/explanation/architecture"}]},"features":[{"icon":"⚙️","title":"Generic over your config model","details":"ConfigSource<T>/ConfigFormat<T> traits — scarab never names a consumer's Config type; each repo brings its own serde model","link":"/reference/config-port","linkText":"config port"},{"icon":"🗂️","title":"Discovery, not hardcoding","details":"explicit path → $<NAME>_CONFIG → ./<name>.<ext> → ~/.config/<name>/ — YAML preferred on ties","link":"/how-to/customize-config-discovery","linkText":"customize discovery"},{"icon":"🧱","title":"Layered configs","details":"LayeredFileSource merges one file per search dir + explicit/override layers as JSON — user config as base, project config on top","link":"/how-to/layered-config","linkText":"layer configs"},{"icon":"🧩","title":"Template packs via tamias","details":"type: template packages render declared files into target paths — install validates, deploy writes, uninstall reverses","link":"/how-to/write-a-template-pack","linkText":"template packs"},{"icon":"🔒","title":"Sandboxed rendering","details":"minijinja engine — templates are third-party content and cannot reach the filesystem or network","link":"/explanation/architecture","linkText":"architecture"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),i={name:"index.md"};function n(s,e,d,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<div style="display:none;" hidden data-nosnippet>Are you an LLM? View /scarab/llms.txt for optimized Markdown documentation, or /scarab/llms-full.txt for full documentation bundle</div><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>Scarab is the org&#39;s config &amp; template expertise: a generic config loading port (<code>ConfigSource&lt;T&gt;</code>/<code>ConfigFormat&lt;T&gt;</code> + a <code>Discovery</code> spec, generic over the consumer&#39;s serde model) and a templated content plane (<code>type: template</code> tamias packs rendered by a sandboxed MiniJinja engine).</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><p>Every repo was copy-pasting the same config-discovery dance — explicit path → <code>$&lt;NAME&gt;_CONFIG</code> → <code>./&lt;name&gt;.&lt;ext&gt;</code> → <code>~/.config/&lt;name&gt;/</code> — and templated dotfiles/config packs had no shared mechanism. Scarab generalizes both once, behind ports, so consumers keep only their <code>Config</code> type.</p><h2 id="boundary" tabindex="-1">Boundary <a class="header-anchor" href="#boundary" aria-label="Permalink to &quot;Boundary&quot;">​</a></h2><ul><li><strong>Owns:</strong> config discovery + formats, the <code>type: template</code> pack model/driver/engine.</li><li><strong>Doesn&#39;t own:</strong> secret values (<a href="https://9aia.com/cuora/" target="_blank" rel="noreferrer">cuora</a>), distribution (<a href="https://9aia.com/tamias/" target="_blank" rel="noreferrer">tamias</a>), releases (<a href="https://9aia.com/tarsi/" target="_blank" rel="noreferrer">tarsi</a>).</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to…</th><th>Go to</th></tr></thead><tbody><tr><td>Load your first typed config</td><td><a href="/scarab/tutorials/getting-started.html">Tutorial</a></td></tr><tr><td>Do a task (custom discovery, layered configs, template packs)</td><td><a href="/scarab/how-to/">How-to</a></td></tr><tr><td>Understand the design (ports, planes, boundaries)</td><td><a href="/scarab/explanation/">Explanation</a></td></tr><tr><td>Look up a trait, type, or pack field</td><td><a href="/scarab/reference/">Reference</a></td></tr></tbody></table>',9)])])}const m=t(i,[["render",n]]);export{g as __pageData,m as default};
